<template>
  <div class="commerce-page settings-page" v-loading="loading">
    <header class="commerce-heading"><div><p class="eyebrow">MAKE IT YOURS</p><h1>{{ first ? '欢迎入驻，先认识一下。' : '店铺设置' }}</h1><p class="intro">{{ first ? '完成以下两步，即可开始经营你的校园店铺。' : '维护店铺信息与账号安全，让每一次发货都有迹可循。' }}</p></div><span class="account-pill"><i class="ph ph-storefront" /> {{ user.profile?.accountCode }}</span></header>
    <div v-if="first" class="onboarding-note"><i class="ph ph-check-circle" /><div><strong>邀请码已激活，账号现已永久保留</strong><p>请修改初始密码 123456 并设置发货城市，完成后即可使用工作台。</p></div></div>
    <el-form ref="formRef" :model="form" :rules="rules" label-position="top" size="large" @submit.prevent="save">
      <div class="settings-grid"><div>
        <section class="surface settings-section"><div class="setting-heading"><span>01</span><div><h3>让大家认识你的店铺</h3><p>店铺名称和发货城市将用于商品展示与订单发货。</p></div></div><div class="avatar-settings"><el-avatar :size="72" :src="user.avatar || undefined">{{ (user.profile?.name||'商').slice(0,1) }}</el-avatar><div><strong>店铺头像</strong><p>{{ first?'完成首次入驻后即可上传店铺头像。':'用于商家主页、店铺入口与工作台展示。' }}</p><el-upload :show-file-list="false" accept="image/jpeg,image/png,image/webp,image/gif,image/bmp" :http-request="uploadAvatar" :disabled="first||avatarUploading||saving"><el-button :disabled="first||saving" :loading="avatarUploading">{{ user.avatar?'更换头像':'上传头像' }}</el-button></el-upload></div></div><div class="cover-settings"><div class="cover-preview" :style="user.profile?.coverUrl?{backgroundImage:`url(${user.profile.coverUrl})`}:{}"><span v-if="!user.profile?.coverUrl">商家主页背景</span></div><div><strong>主页背景</strong><p>为店铺主页设置背景图，建议使用横向图片。</p><el-upload :show-file-list="false" accept="image/jpeg,image/png,image/webp,image/gif,image/bmp" :http-request="uploadCover" :disabled="first||coverUploading||saving"><el-button :disabled="first||saving" :loading="coverUploading">{{ user.profile?.coverUrl?'更换主页背景':'上传主页背景' }}</el-button></el-upload></div></div><el-form-item label="店铺名称" prop="name"><el-input v-model="form.name" placeholder="给你的店铺起个好名字" maxlength="80" show-word-limit /></el-form-item><el-form-item label="发货城市" prop="city"><div class="city-input"><el-autocomplete v-model="form.city" :fetch-suggestions="suggestCity" placeholder="例如：浙江省杭州市，也可直接填写城市" maxlength="80" clearable /><el-button :loading="locating" :disabled="!canLocate" @click="locate"><i class="ph ph-crosshair" /> 获取定位</el-button></div></el-form-item><p class="field-hint">{{ canLocate ? '点击定位后，请核对识别出的城市；也可以随时手动修改。' : '请手动填写发货城市；自动识别城市尚未启用。' }}</p><p v-if="canLocate" class="field-hint">城市识别由高德地图提供，仅保存城市名称。</p></section>
        <section class="surface settings-section"><div class="setting-heading"><span>02</span><div><h3>{{ first ? '设置属于你的安全密码' : '修改登录密码' }}</h3><p>{{ first ? '初始密码仅用于首次入驻，请设置新的密码。' : '如无需修改密码，可将以下三项留空。' }}</p></div></div><el-form-item label="当前密码" prop="currentPassword"><el-input v-model="form.currentPassword" type="password" show-password autocomplete="current-password" :placeholder="first ? '初始密码为 123456' : '请输入当前密码'" /></el-form-item><div class="password-grid"><el-form-item label="新密码" prop="newPassword"><el-input v-model="form.newPassword" type="password" show-password autocomplete="new-password" placeholder="至少8位，包含字母和数字" maxlength="72" /></el-form-item><el-form-item label="确认新密码" prop="confirmPassword"><el-input v-model="form.confirmPassword" type="password" show-password autocomplete="new-password" placeholder="再次输入新密码" maxlength="72" /></el-form-item></div></section>
        <div class="settings-actions"><span>账号：{{ user.profile?.accountCode }} · 长期有效</span><el-button type="primary" size="large" :loading="saving" :disabled="avatarUploading||coverUploading" native-type="submit">{{ first ? '完成设置，开启经营' : '保存店铺设置' }} <i class="ph ph-arrow-right" /></el-button></div>
      </div><aside class="settings-guide"><i class="ph ph-sparkle" /><h2>好的开始，<br />从这里发生。</h2><p>一个让人记得住的店铺名，<br />一个清晰的发货城市，<br />还有一份用心挑选的好物。</p><div><i class="ph ph-shield-check" /><span>专属商家账号<br /><small>由管理员邀请，首次登录后永久激活</small></span></div><div><i class="ph ph-map-pin" /><span>城市级发货信息<br /><small>为买家展示准确的发货来源</small></span></div></aside></div>
    </el-form>
  </div>
</template>
<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { useUserStore } from '@/stores/user'
import { ElMessage } from 'element-plus'
import { uploadImage } from '@/api/file'
import { locationAvailable, locateCity, saveMerchantProfile, saveMerchantAvatar, saveMerchantCover } from '@/api/merchant'
const user=useUserStore(),router=useRouter(),formRef=ref(),loading=ref(false),saving=ref(false),locating=ref(false),canLocate=ref(false)
const avatarUploading=ref(false),coverUploading=ref(false)
const first=computed(()=>Number(user.profile?.mustChangePassword)===1)
const form=reactive({name:'',city:'',currentPassword:'',newPassword:'',confirmPassword:''})
const passwordCheck=(_r,v,done)=>{if((first.value||form.newPassword||form.currentPassword||form.confirmPassword)&&(!/^(?=.*[A-Za-z])(?=.*\d).{8,72}$/.test(form.newPassword)))done(new Error('密码需为8–72位，包含字母和数字'));else done()}
const rules={name:[{required:true,message:'请填写店铺名称',trigger:'blur'}],city:[{required:true,message:'请填写发货城市',trigger:'blur'}],currentPassword:[{validator:(_r,v,d)=>{if((first.value||form.newPassword)&&!v)d(new Error('请输入当前密码'));else d()},trigger:'blur'}],newPassword:[{validator:passwordCheck,trigger:'blur'}],confirmPassword:[{validator:(_r,v,d)=>{if(v!==form.newPassword)d(new Error('两次输入的密码不一致'));else d()},trigger:'blur'}]}
const cities=['北京市','上海市','天津市','重庆市','浙江省杭州市','浙江省宁波市','江苏省南京市','江苏省苏州市','广东省广州市','广东省深圳市','四川省成都市','湖北省武汉市','湖南省长沙市','陕西省西安市','山东省济南市','山东省青岛市','福建省福州市','福建省厦门市','河南省郑州市','安徽省合肥市','江西省南昌市','云南省昆明市','贵州省贵阳市','广西南宁市','辽宁省沈阳市','吉林省长春市','黑龙江省哈尔滨市','河北省石家庄市','山西省太原市','海南省海口市']
function suggestCity(query,cb){cb(cities.filter(c=>!query||c.includes(query)).slice(0,12).map(value=>({value})))}
async function locate(){
  if(!navigator.geolocation||!window.isSecureContext){ElMessage.info('当前环境无法获取定位，请手动填写城市');return}
  locating.value=true
  try{const pos=await new Promise((resolve,reject)=>navigator.geolocation.getCurrentPosition(resolve,reject,{timeout:10000,enableHighAccuracy:false,maximumAge:300000}));const r=await locateCity(pos.coords.latitude,pos.coords.longitude);form.city=r.data.city;ElMessage.success('已识别城市，请核对')}catch(e){if(e.code)ElMessage.info('未能获取定位，请手动填写城市')}finally{locating.value=false}
}
async function uploadAvatar({file,onSuccess,onError}){avatarUploading.value=true;try{const r=await uploadImage(file);await saveMerchantAvatar(r.data.url);await user.refreshProfile();ElMessage.success('店铺头像已更新');onSuccess(r)}catch(e){onError(e)}finally{avatarUploading.value=false}}
async function uploadCover({file,onSuccess,onError}){coverUploading.value=true;try{const r=await uploadImage(file);await saveMerchantCover(r.data.url);await user.refreshProfile();ElMessage.success('主页背景已更新');onSuccess(r)}catch(e){onError(e)}finally{coverUploading.value=false}}
async function save(){if(saving.value||avatarUploading.value||coverUploading.value)return;const valid=await formRef.value.validate().catch(()=>false);if(!valid)return;saving.value=true;const wasFirst=first.value;try{const r=await saveMerchantProfile(form);user.applyAuth(r.data);form.currentPassword='';form.newPassword='';form.confirmPassword='';ElMessage.success(wasFirst?'入驻完成，欢迎开启经营':'店铺设置已保存');if(wasFirst)router.replace('/merchant/home')}catch{}finally{saving.value=false}}
onMounted(async()=>{loading.value=true;try{await user.refreshProfile();form.name=user.profile?.name||'';form.city=user.profile?.city||'';canLocate.value=(await locationAvailable()).data.available}catch{}finally{loading.value=false}})
</script>
<style scoped>
.cover-settings{display:flex;align-items:center;gap:20px;padding:18px;background:#f7f8f2;border-radius:14px;margin-bottom:24px}.cover-preview{width:140px;height:80px;flex-shrink:0;background:linear-gradient(125deg,#3a6250,#b3b288);background-size:cover;background-position:center;display:grid;place-items:center;border-radius:10px;color:#f4f2de;font-size:11px}.cover-settings strong{font-size:14px}.cover-settings p{font-size:11px;color:#919e80;line-height:1.8;margin:6px 0 12px}@media(max-width:600px){.cover-settings{flex-direction:column;align-items:flex-start}.cover-preview{width:100%;height:100px}}
.avatar-settings{display:flex;align-items:center;gap:20px;padding:18px;background:#f7f8f2;border-radius:14px;margin-bottom:24px}.avatar-settings :deep(.el-avatar){flex-shrink:0;background:#b88b4c;color:#fff5dc;font-size:26px}.avatar-settings strong{font-size:14px}.avatar-settings p{font-size:11px;color:#919e80;line-height:1.8;margin:6px 0 12px}
.settings-page{max-width:1180px}.account-pill{display:flex;align-items:center;gap:8px;font-size:11px;color:#89927c;padding:12px 15px;border:1px solid #dfe4d5;border-radius:30px}.onboarding-note{display:flex;align-items:center;gap:14px;background:#e9f0e1;border:1px solid #d8e4cd;border-radius:14px;padding:18px 24px;margin-bottom:24px;color:#527344}.onboarding-note>i{font-size:27px}.onboarding-note strong{font-size:14px}.onboarding-note p{margin:6px 0 0;font-size:12px;line-height:1.7;color:#81936b}.settings-grid{display:grid;grid-template-columns:minmax(0,1fr) 285px;gap:24px}.settings-section{margin-bottom:20px}.setting-heading{display:flex;gap:14px;align-items:flex-start;margin-bottom:24px}.setting-heading>span{font-size:11px;color:#8a946f;background:#eff2e6;border-radius:8px;padding:7px 9px}.setting-heading h3{font-size:16px;margin:0 0 8px}.setting-heading p{font-size:12px;line-height:1.7;color:#9aa18b;margin:0}.city-input{display:flex;width:100%;gap:12px}.city-input .el-autocomplete{flex:1}.city-input i{margin-right:6px}.field-hint{font-size:11px;color:#99a188;line-height:1.8;margin:4px 0}.password-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.settings-actions{display:flex;justify-content:space-between;align-items:center;gap:14px}.settings-actions>span{font-size:11px;color:#a0a58e}.settings-actions i{margin-left:15px}.settings-guide{border-radius:20px;padding:30px;background:#e5e6d4;align-self:start;position:sticky;top:0}.settings-guide>i{font-size:29px;color:#a18d56}.settings-guide h2{font-family:Georgia,serif;font-size:28px;line-height:1.6;color:#4c6140;margin:22px 0}.settings-guide p{font-size:12px;line-height:2.3;color:#8a9475;margin-bottom:35px}.settings-guide>div{display:flex;gap:10px;margin:25px 0 0;font-size:12px;line-height:1.8;color:#60754e}.settings-guide>div>i{font-size:20px}.settings-guide small{font-size:10px;color:#9aa17f}@media(max-width:1100px){.settings-grid{grid-template-columns:1fr}.settings-guide{display:none}}@media(max-width:650px){.password-grid{grid-template-columns:1fr;gap:0}.settings-actions{flex-direction:column;align-items:flex-end}.city-input{flex-direction:column}.account-pill{display:none}}
</style>
